// radio_golden_2026_apr7_morning.js — Radiology 7 April Morning 2026 paper (161 source MCQs, #161 ignored per user instruction = 160 total)
// Schema: {q,o,a,e} with 5 options A-E and answer index 0-4
// Explanation: P1 mechanism + Take Notes discriminator chain (target ~50 words total)
if(!window.MM) window.MM={};
window.MM['radio_golden_2026_apr7_morning']=[
/*1*/ {"q":"Cartilage damage in children is caused by which drug?","o":["Metronidazole","Ciprofloxacin","Azithromycin","Erythromycin","Doxycycline"],"a":1,"e":"Fluoroquinolones (ciprofloxacin) cause arthropathy and cartilage damage in growing children; reversible joint pain and cartilage erosion in animal studies. Avoided in children and pregnancy except in severe pediatric infections.<br><br>Take Notes: Tetracyclines → teeth/bone discoloration | Metronidazole → no cartilage effect | Pediatric cartilage damage = fluoroquinolones."},
/*2*/ {"q":"Degeneration of substantia nigra is seen in which disease?","o":["Cerebellar disease","Multisystem atrophy","Parkinson disease","ALS","Huntington disease"],"a":2,"e":"Parkinson disease: degeneration of dopaminergic neurons in substantia nigra pars compacta of midbrain; loss of dopamine input to striatum causes resting tremor, rigidity, bradykinesia, postural instability.<br><br>Take Notes: ALS → motor neurons | Huntington → caudate atrophy | Substantia nigra degeneration = Parkinson disease."},
/*3*/ {"q":"Which of the following is the most prominent step in irreversible cell injury?","o":["Cell membrane damage","Massive calcium influx","Cellular swelling","Mitochondrial swelling","Nuclear pyknosis"],"a":0,"e":"Cell membrane damage is the hallmark of irreversible cell injury; loss of membrane integrity allows uncontrolled calcium entry and enzyme leakage. Plasma membrane disruption distinguishes irreversible from reversible injury.<br><br>Take Notes: Cellular swelling → reversible first sign | Mitochondrial swelling → reversible | Irreversible injury hallmark = cell membrane damage."},
/*4*/ {"q":"Most prominent feature of reversible cell injury:","o":["Myeline figure","Cellular swelling","Mitochondrial dysfunction","Atrophy","Nuclear pyknosis"],"a":1,"e":"Cellular swelling (hydropic change) is the earliest and most prominent feature of reversible cell injury; results from ATP depletion impairing Na/K-ATPase, causing sodium and water accumulation intracellularly.<br><br>Take Notes: Myelin figures → late changes | Atrophy → chronic adaptation | Earliest reversible injury = cellular swelling."},
/*5*/ {"q":"ECG of patient shows no association between P-R waves and had history of fainting due to:","o":["1st degree heart block","2nd degree heart block","3rd degree heart block","Mobitz block","Sinus arrhythmia"],"a":2,"e":"Third-degree (complete) heart block: no association between atrial (P waves) and ventricular (QRS) activity; AV dissociation causes inadequate ventricular rate leading to syncope (Stokes-Adams attacks). Requires pacemaker.<br><br>Take Notes: 1st degree → prolonged PR only | 2nd degree Mobitz → variable PR or dropped beats | No P-QRS association = 3rd degree (complete)."},
/*6*/ {"q":"Most common site of subdural hematoma?","o":["Occipital lobe","Parietal and frontal lobes","Temporal lobe","Premotor cortex","Cerebellum"],"a":1,"e":"Subdural hematoma occurs most commonly over the cerebral convexities, particularly the frontal and parietal lobes; due to tearing of bridging veins between brain and dural venous sinuses (most vulnerable here).<br><br>Take Notes: Temporal → epidural (middle meningeal) | Cerebellum → uncommon | Subdural hematoma site = parietal + frontal lobes."},
/*7*/ {"q":"A patient with flat facies, small eyes, microcephaly is associated with which syndrome?","o":["Fragile X syndrome","Edward syndrome","Patau syndrome","Down syndrome","Noonan syndrome"],"a":2,"e":"Patau syndrome (trisomy 13): microcephaly, holoprosencephaly, microphthalmia (small eyes), cleft lip/palate, polydactyly, cardiac defects. Survival usually <1 year. Most severe trisomy.<br><br>Take Notes: Edwards (trisomy 18) → rocker-bottom feet, clenched fists | Down (trisomy 21) → epicanthal folds | Microcephaly + small eyes = Patau."},
/*8*/ {"q":"Early adolescent with prominent forehead, looking ears and long longitudinal mandible and hypergonadism is clinically diagnostic of:","o":["Down syndrome","Turner syndrome","Fragile X syndrome","Klinefelter syndrome","Patau syndrome"],"a":2,"e":"Fragile X syndrome: most common inherited intellectual disability; long face with prominent forehead, large ears, large jaw, macroorchidism (post-pubertal), autism, mitral valve prolapse. FMR1 gene CGG repeat expansion.<br><br>Take Notes: Klinefelter → tall, small testes | Down → epicanthal folds | Macroorchidism + large ears + prominent forehead = Fragile X."},
/*9*/ {"q":"Grading of tumor depends on:","o":["Degree of differentiation","Cell number","Invasion","All of the above","TNM classification"],"a":0,"e":"Tumor grading reflects degree of differentiation — how closely tumor cells resemble normal tissue. Well-differentiated (low grade) vs poorly differentiated (high grade). Staging assesses extent (invasion, metastasis).<br><br>Take Notes: Staging → extent (TNM) | Grading = degree of differentiation."},
/*10*/ {"q":"Spared reflexes occur in:","o":["UMN lesions","LMN lesions","Early ALS","Parkinson","Spinal shock"],"a":1,"e":"LMN lesions cause loss of reflexes (hyporeflexia/areflexia) due to disruption of motor unit. \"Spared\" reflexes in a damaged area indicate UMN lesion above (where reflexes are exaggerated, not lost).<br><br>Take Notes: UMN → hyperreflexia | Early ALS → mixed UMN+LMN | Lost (spared from preservation) reflexes = LMN."},
/*11*/ {"q":"Omeprazole inhibits which structure?","o":["Na/K pump","H+/K+ ATPase (proton pump)","H ATPase","Na ATPase","Cl/HCO3 exchanger"],"a":1,"e":"Omeprazole and other proton pump inhibitors (PPIs) irreversibly inhibit H+/K+-ATPase (proton pump) in gastric parietal cells; profoundly reduce gastric acid secretion. Used for PUD, GERD, H. pylori eradication.<br><br>Take Notes: H2 blockers → histamine receptor | Antacids → neutralize acid | PPI MOA = H+/K+ ATPase inhibition."},
/*12*/ {"q":"Gastric carcinoma involving the left upper side of stomach will spread first to which lymph node?","o":["Superior mesenteric nodes","Celiac nodes","Pancreaticosplenic nodes","Inferior mesenteric nodes","Gastroepiploic nodes"],"a":2,"e":"Greater curvature of stomach (left upper side) drains primarily to pancreaticosplenic lymph nodes (along splenic artery); these subsequently drain to celiac nodes. Tumor of left upper stomach spreads there first.<br><br>Take Notes: Lesser curvature → left gastric nodes | Pylorus → pyloric nodes | Greater curvature/fundus = pancreaticosplenic."},
/*13*/ {"q":"End product of glycolysis in absence of mitochondria?","o":["Lactic acid","1 molecule of pyruvic acid","2 mol of pyruvic acid","3 molecules of pyruvic acid","Acetyl-CoA"],"a":0,"e":"Glycolysis in absence of mitochondria (anaerobic conditions): 1 glucose → 2 pyruvate, then converted to lactate by LDH to regenerate NAD+. Net product is lactate (lactic acid).<br><br>Take Notes: Aerobic → 2 pyruvate enter TCA | Anaerobic = lactate (end product) | Net glycolysis = 2 pyruvate but final anaerobic product = lactic acid."},
/*14*/ {"q":"A 10-year-old child presents with corneal opacities and mild anemia. Lab investigations show increased free cholesterol, decreased cholesterol esters and HDL levels. Further evaluation reveals that free cholesterol cannot be processed in the plasma due to an enzymatic defect. Which enzyme is most likely deficient?","o":["Lecithin-cholesterol acyltransferase (LCAT)","Acyl-CoA acyltransferase (ACAT)","HMG-CoA reductase","Apolipoprotein A1","Cholesterol esterase"],"a":0,"e":"LCAT (Lecithin-cholesterol acyltransferase) catalyzes esterification of cholesterol in HDL; deficiency causes accumulation of free cholesterol, reduced cholesterol esters, low HDL, corneal opacities (fish-eye disease), and anemia.<br><br>Take Notes: ACAT → intracellular cholesterol esterification | HMG-CoA reductase → cholesterol synthesis | Corneal opacities + low HDL = LCAT deficiency."},
/*15*/ {"q":"65-year-old patient presents with episodes of dizziness. ECG findings reveal a regular RR interval, visible P waves, and a 2:1 AV conduction pattern. Most likely diagnosis?","o":["Mobitz Type 1","Mobitz Type 2","Third degree (complete) heart block","First-degree heart block","Atrial fibrillation"],"a":1,"e":"Mobitz Type 2 second-degree AV block: regular RR interval with fixed 2:1 (or 3:1) ratio between P waves and QRS complexes. Higher risk of progression to complete heart block; pacemaker often required.<br><br>Take Notes: Mobitz Type 1 → progressive PR prolongation (Wenckebach) | Mobitz Type 2 = fixed PR + dropped beats (2:1)."},
/*16*/ {"q":"Regarding primary motor cortex:","o":["Does not receive sensory input","Receives sensory input and gives motor response accordingly","Is present only in frontal lobe","Does not control fine motor movements","Is involved in coordination of smoother motor response"],"a":1,"e":"Primary motor cortex (precentral gyrus, area 4) receives sensory input from somatosensory cortex (via association fibers) and integrates this with motor commands for adaptive movements; works with cerebellum for smooth motion.<br><br>Take Notes: Premotor cortex → planning | Frontal eye field → eye movements | Primary motor cortex = sensory input + motor output."},
/*17*/ {"q":"Formula for calculating the loading dose of a drug?","o":["(Target concentration × Volume of distribution) / Bioavailability","Clearance × Target concentration","Volume of distribution / Target concentration","Target concentration / (Volume of distribution × Bioavailability)","(Clearance × Bioavailability) / Target concentration"],"a":0,"e":"Loading dose = (Target concentration × Volume of distribution) / Bioavailability. Used to rapidly achieve therapeutic level. For IV (F=1), simplifies to Target × Vd. Maintenance dose involves clearance.<br><br>Take Notes: Maintenance dose = Clearance × Target conc / F | Loading dose = Vd × target / F."},
/*18*/ {"q":"Central cord syndrome typically presents with:","o":["Upper limbs affected more than lower limbs","Lower limbs affected more than upper limbs","Equal involvement of upper and lower limbs","Only sensory loss without motor involvement","Complete quadriplegia"],"a":0,"e":"Central cord syndrome: cervical cord central injury (often from hyperextension in elderly with spondylosis); affects upper limbs more than lower limbs (\"man-in-the-barrel\" appearance) because cervical fibers are medial in corticospinal tract.<br><br>Take Notes: Anterior cord → motor + pain/temp loss | Brown-Séquard → hemisection | Central cord = upper > lower limbs."},
/*19*/ {"q":"Old age diabetic patient having multiple abscesses. Supportive inflammatory cells reach inflammation area by:","o":["Post capillary venules","Capillaries","Veins","Arteries","Lymphatic vessels"],"a":0,"e":"Leukocyte migration into tissues during inflammation occurs primarily at post-capillary venules; this is where rolling, adhesion, and transmigration (diapedesis) take place. Selectins, integrins, and ICAM-1/VCAM-1 mediate the process.<br><br>Take Notes: Arteries → no leukocyte exit | Capillaries → minor role | Inflammation extravasation site = postcapillary venules."},
/*20*/ {"q":"4-year-old child is brought to the pediatric clinic for developmental assessment. He has a distinctive \"elfin\" facial appearance, is extremely friendly with strangers, and shows relatively strong verbal skills but poor visuospatial abilities. On cardiovascular exam, a systolic murmur and echocardiography reveal supravalvular aortic stenosis. Serum calcium is elevated. Which of the following proteins is most likely affected in this patient?","o":["Fibrillin","Dystrophin","Collagen type I","Elastin","Laminin"],"a":3,"e":"Williams syndrome: 7q11.23 microdeletion involving ELN (elastin gene); supravalvular aortic stenosis, elfin facies, hypercalcemia, friendly personality (\"cocktail party\" demeanor), intellectual disability, strong verbal abilities.<br><br>Take Notes: Fibrillin → Marfan | Dystrophin → Duchenne | Collagen → Ehlers-Danlos | Williams = elastin deficiency."},
/*21*/ {"q":"A patient is having bleeding problem. Lab shows PT increased, APTT normal and bleeding time normal and defect in which of following pathway?","o":["Extrinsic pathway","Intrinsic pathway","Platelet function","Clot Retraction","Blood Propagation"],"a":0,"e":"Prolonged PT with normal APTT and normal bleeding time indicates extrinsic pathway defect (factor VII deficiency or vitamin K deficiency early on). PT measures extrinsic pathway; APTT measures intrinsic.<br><br>Take Notes: APTT prolonged → intrinsic pathway | Bleeding time → platelet | Isolated PT prolongation = extrinsic pathway defect."},
/*22*/ {"q":"Nutmeg liver cause is:","o":["Periportal congestion","Centrilobular congestion","Peripheral congestion","Chronic passive congestion","Acute hepatitis"],"a":3,"e":"Nutmeg liver appearance results from chronic passive congestion of liver, typically due to right-sided heart failure; centrilobular hepatocyte necrosis with congestion gives the speckled \"nutmeg\" pattern on cut surface.<br><br>Take Notes: Centrilobular congestion = histologic finding | RHF/cor pulmonale → cause | Nutmeg liver gross appearance = chronic passive congestion."},
/*23*/ {"q":"Which organ is most likely to escape ischemic damage due to dual blood supply?","o":["Spleen","Liver","Kidney","Brain","Heart"],"a":1,"e":"Liver has dual blood supply: hepatic artery (~25%) and portal vein (~75%); occlusion of one source rarely causes infarction. Liver is resistant to ischemic damage compared to organs with single supply.<br><br>Take Notes: Spleen → splenic artery only (end-arterial) | Brain → end-arteries | Dual blood supply organ = liver."},
/*24*/ {"q":"A 3-month-old infant presents with difficulty feeding and a pan-systolic murmur. What is the most likely diagnosis?","o":["Atrial septal defect (ASD)","Ventricular septal defect (VSD)","Patent ductus arteriosus (PDA)","Pulmonary stenosis","Aortic stenosis"],"a":1,"e":"VSD is the most common congenital heart defect (30%); pansystolic murmur at left lower sternal border. Infant with difficulty feeding (failure to thrive from heart failure) is classic presentation.<br><br>Take Notes: ASD → fixed split S2, mid-systolic | PDA → continuous machinery murmur | Pansystolic + infant = VSD."},
/*25*/ {"q":"Fecal continence is maintained by which spinal segments?","o":["L4, L5","S1, S2","S2, S3, S4","T10, T11, T12","L2, L3"],"a":2,"e":"Fecal (and urinary) continence is maintained by sacral spinal cord segments S2, S3, S4 (mnemonic \"S2,3,4 keeps the poop off the floor\"); somatic pudendal nerve supplies external anal sphincter.<br><br>Take Notes: Bladder/bowel/sex = S2-S4 | Pudendal nerve = somatic motor | Fecal continence = S2-S4."},
/*26*/ {"q":"A 3-year-old child died. His autopsy report shows multiple cysts in row in kidney. What is inheritance pattern?","o":["Autosomal recessive","Autosomal dominant","X-linked dominant","X-linked recessive","Mitochondrial"],"a":0,"e":"Autosomal recessive polycystic kidney disease (ARPKD): bilateral renal cysts in infants/children, typically fatal in infancy. Distinct from adult-onset autosomal dominant PKD which presents later.<br><br>Take Notes: ADPKD → adult onset (autosomal dominant) | ARPKD → child onset (autosomal recessive) | Pediatric PKD = autosomal recessive."},
/*27*/ {"q":"A 26-year-old male patient after RTA is undergoing nasogastric tube insertion. The late anatomical obstruction typically encountered during this procedure is at the:","o":["Carina of trachea","Esophageal hiatus","Esophagopharyngeal junction","Pylorus of stomach","Lower esophageal sphincter"],"a":1,"e":"Nasogastric tube passes through three constrictions: cricopharyngeal junction (early), aortic crossing/left bronchus (middle), and esophageal hiatus through diaphragm (late). The diaphragmatic hiatus is the last natural narrowing before stomach.<br><br>Take Notes: Early point → piriform fossa | Late point = esophageal hiatus | NG tube late obstruction = esophageal hiatus."},
/*28*/ {"q":"Patient underwent gastrectomy and has now developed pernicious anemia due to deficiency of Vitamin B12. The cells required for the absorption of Vitamin B12 are:","o":["Parietal cells","Mucous cells","Serous cells","Brunner cells","Chief cells"],"a":0,"e":"Parietal cells in gastric body and fundus secrete intrinsic factor (IF), required for vitamin B12 absorption in terminal ileum. Gastrectomy removes parietal cells, causing IF deficiency and B12 malabsorption.<br><br>Take Notes: Chief cells → pepsinogen | G cells → gastrin | IF and B12 absorption = parietal cells."},
/*29*/ {"q":"A neonate brought from the nursery develops a generalized vesicular rash. The lesions are present in different stages and appear as clear vesicles on an erythematous base, described as \"dew drops on rose petals.\" Most likely causative organism is:","o":["Measles virus","Varicella zoster virus","Rubella virus","Streptococcus pyogenes","Human herpesvirus-6"],"a":1,"e":"Varicella (chickenpox): vesicular rash in different stages (papules, vesicles, crusts) simultaneously; classic \"dew drops on rose petals\" appearance. VZV is highly contagious; neonatal varicella has high mortality.<br><br>Take Notes: Measles → maculopapular (Koplik spots) | Rubella → mild maculopapular | HHV-6 → roseola | Vesicles in stages = VZV."},
/*30*/ {"q":"A 35-year-old male patient with HIV presents with 2-week history of fever, non-productive cough and shortness of breath. He is cachectic and reports night sweats and weight loss. His CD4 cell count is <200 and chest X-ray reveals bilateral diffuse infiltrates. What is the most likely causative organism?","o":["Streptococcus pneumoniae","Mycobacterium tuberculosis","Pneumocystis jiroveci","Staphylococcus aureus","Cryptococcus"],"a":2,"e":"Pneumocystis jirovecii pneumonia (PJP) is the most common opportunistic pneumonia in HIV patients with CD4 <200; non-productive cough, dyspnea, fever, bilateral diffuse interstitial infiltrates on CXR. Treated with TMP-SMX.<br><br>Take Notes: TB → cavitations + apical | Strep pneumoniae → lobar consolidation | HIV + CD4<200 + bilateral diffuse = PJP."},
/*31*/ {"q":"A person had a penetrating injury in the axilla. Later, he presented with weakness of shoulder abduction and loss of sensation over the lateral aspect of the upper arm. Which nerve is most likely injured?","o":["Radial nerve","Axillary nerve","Musculocutaneous nerve","Ulnar nerve","Suprascapular nerve"],"a":1,"e":"Axillary nerve injury: shoulder abduction loss (deltoid paralysis) and sensory loss over regimental badge area (lateral upper arm). Common with shoulder dislocation, humeral surgical neck fracture, or axillary trauma.<br><br>Take Notes: Radial → wrist drop, posterior arm | Musculocutaneous → elbow flexion + lateral forearm | Shoulder abduction + lateral arm = axillary."},
/*32*/ {"q":"A CKD patient develops bleeding after nephrostomy. What is the most appropriate blood product to administer?","o":["Packed RBCs","Platelets","Fresh frozen plasma (FFP)","Cryoprecipitate","Whole blood"],"a":3,"e":"CKD patients have uremic platelet dysfunction causing bleeding. Cryoprecipitate (contains vWF, factor VIII, fibrinogen, factor XIII) improves platelet adhesion and is the most appropriate first-line product for uremic bleeding.<br><br>Take Notes: Desmopressin → also effective in uremia | FFP → for coagulation factor deficiency | Uremic bleeding = cryoprecipitate."},
/*33*/ {"q":"Inspiratory ramp signals are produced from dorsal respiratory neurons. Their rate increases in response to impulses from:","o":["Stretch receptors in lung","Pneumotaxic centre in pons","Apneustic centre","Mid brain","Pons"],"a":2,"e":"Apneustic center (lower pons) stimulates dorsal respiratory group neurons producing inspiratory ramp signals — gradually increasing inspiratory drive. Pneumotaxic center inhibits inspiration. Both modulate basic medullary rhythm.<br><br>Take Notes: Pneumotaxic → inhibits inspiration | Stretch receptors → Hering-Breuer reflex | Apneustic = stimulates inspiratory ramp."},
/*34*/ {"q":"What is the protein defect associated with supravalvular aortic stenosis?","o":["Collagen","Elastin","Fibrillin","Myosin","Troponin"],"a":1,"e":"Williams syndrome (supravalvular aortic stenosis): elastin (ELN gene, 7q11.23) deficiency from microdeletion causes elastic fiber abnormalities in aorta and other elastic arteries. Other features: elfin facies, hypercalcemia, intellectual disability.<br><br>Take Notes: Fibrillin → Marfan | Collagen → Ehlers-Danlos | Supravalvular AS = elastin deficiency (Williams)."},
/*35*/ {"q":"Which organism is responsible for rheumatic fever?","o":["Group A Streptococcus","Group B Streptococcus","Group C Streptococcus","Staphylococcus aureus","Streptococcus pneumoniae"],"a":0,"e":"Group A β-hemolytic Streptococcus (S. pyogenes) is the causative organism of acute rheumatic fever; 2-4 weeks after pharyngitis. Molecular mimicry between bacterial M protein and host antigens causes cross-reactive immune injury.<br><br>Take Notes: Group B strep → neonatal sepsis | Strep pneumoniae → pneumonia | Rheumatic fever = Group A strep."},
/*36*/ {"q":"A male with history of travel to Bangkok, presented with painless penile ulcer with localized lymphadenopathy that were found to be rubbery and painless on examination, additionally he had rash on his palms and soles due to:","o":["Primary syphilis","Secondary syphilis","Tertiary syphilis","Latent syphilis","Cardiac syphilis"],"a":1,"e":"Secondary syphilis: 4-10 weeks after primary chancre, presents with maculopapular rash including palms and soles, painless lymphadenopathy, condyloma lata, mucous patches. Treponema pallidum infection.<br><br>Take Notes: Primary → painless chancre alone | Tertiary → gummas, neurosyphilis | Rash on palms/soles + LN = secondary syphilis."},
/*37*/ {"q":"A stone in the parotid gland typically blocks which structure?","o":["Wharton's duct","Stensen's duct","Submandibular duct","Bartholin's duct","Lacrimal duct"],"a":1,"e":"Stensen's duct (parotid duct) drains parotid gland; opens into oral cavity opposite upper second molar. Parotid stones (sialolithiasis) typically obstruct Stensen's duct. Sialolithiasis more common in submandibular gland.<br><br>Take Notes: Wharton's duct → submandibular gland | Bartholin's → vestibular gland (different) | Parotid duct = Stensen's."},
/*38*/ {"q":"What is the initial test commonly used to differentiate between Cushing disease and Cushing's syndrome?","o":["Serum glucose tolerance test","24-hour urinary cortisol test","Serum cortisol levels","Low dose dexamethasone suppression test","ACTH stimulation test"],"a":3,"e":"Low-dose dexamethasone suppression test: screens for Cushing syndrome (failure to suppress cortisol). High-dose dexamethasone test then differentiates Cushing disease (pituitary, suppresses) from ectopic ACTH or adrenal tumor (no suppression).<br><br>Take Notes: 24h urinary cortisol → also screening | High-dose test = Cushing disease vs ectopic | Initial differentiation = low-dose dex suppression."},
/*39*/ {"q":"Diastolic cardiac arrest is caused by which electrolyte abnormality?","o":["Hypokalemia","Hyperkalemia","Hyponatremia","Hypernatremia","Hypocalcemia"],"a":1,"e":"Hyperkalemia causes diastolic cardiac arrest: elevated extracellular K+ depolarizes resting membrane potential, eventually preventing depolarization and contraction. Hypokalemia causes systolic arrest (in flaccid systole).<br><br>Take Notes: Hypokalemia → systolic arrest | Hypocalcemia → tetany, QT prolongation | Diastolic cardiac arrest = hyperkalemia."},
/*40*/ {"q":"A 50-year-old patient presents with diplopia, ptosis, weakness in chewing after prolonged effort, normal pupils, dryness of mouth, proximal muscle weakness, and loss of deep tendon reflexes. Most likely diagnosis?","o":["Myasthenia gravis","Lambert-Eaton syndrome","Multiple sclerosis","Botulism","Guillain-Barré syndrome"],"a":1,"e":"Lambert-Eaton myasthenic syndrome (LEMS): presynaptic Ca²⁺ channel antibodies cause autonomic dysfunction (dry mouth), proximal weakness, areflexia, and improvement with repetitive use. Associated with small cell lung cancer.<br><br>Take Notes: Myasthenia gravis → worsens with use + normal reflexes | LEMS = improves with use + areflexia + autonomic."},
/*41*/ {"q":"For the treatment of diabetic gastroparesis, which drug is most useful?","o":["Prokinetics","Anti-diarrheals","Octreotide","PPIs","Loperamide"],"a":0,"e":"Diabetic gastroparesis (delayed gastric emptying): treatment with prokinetics like metoclopramide (dopamine D2 antagonist) or domperidone; erythromycin (motilin agonist) is short-term option. They enhance gastric motility.<br><br>Take Notes: PPIs → no effect on motility | Octreotide → slows motility | Gastroparesis = prokinetics (metoclopramide)."},
/*42*/ {"q":"A patient presents with recurrent oral and genital ulcers associated with HLA-B5. Cause is:","o":["Reactive arthritis","Ankylosing spondylitis","Behçet disease","Genital ulcer","Uveitis"],"a":2,"e":"Behçet disease: triad of recurrent oral aphthous ulcers, genital ulcers, and uveitis. Multisystem vasculitis associated with HLA-B51 (B5) particularly in Mediterranean and East Asian populations. Pathergy test positive.<br><br>Take Notes: Reactive arthritis → conjunctivitis + arthritis + urethritis | HLA-B27 → AS | HLA-B5 + oral/genital ulcers = Behçet."},
/*43*/ {"q":"A patient presented with bilateral ptosis with muscle wasting on mastication and decrease voice until no voice uttered, diagnosed as myasthenia gravis. Best test for it?","o":["Anti-calcium antibodies","EMG","Edrophonium","ACh receptor antibodies","Tensilon test"],"a":3,"e":"Acetylcholine receptor antibodies (anti-AChR) are the most specific test for myasthenia gravis (85% sensitive). Edrophonium (Tensilon) test gives transient improvement but is less specific. EMG shows decremental response.<br><br>Take Notes: Tensilon → quick bedside test (less specific) | EMG → repetitive stimulation decrement | MG specific test = anti-AChR antibodies."},
/*44*/ {"q":"Which of following cause complement fixation?","o":["IgA","IgM","IgG2","IgGD","IgE"],"a":1,"e":"IgM is the most efficient activator of classical complement pathway due to its pentameric structure (single IgM molecule sufficient with 5 Fc regions). IgG also activates complement but multiple molecules needed.<br><br>Take Notes: IgA → mucosal, doesn't fix complement | IgE → allergy | Best complement fixator = IgM (pentameric)."},
/*45*/ {"q":"A farmer presents with hyperkeratosis, parakeratosis, atypical cells and brown color lesion on face and cheek. Most likely is:","o":["Actinic keratosis","Seborrheic dermatitis","Squamous cell carcinoma","Basal cell carcinoma","Melanoma"],"a":0,"e":"Actinic keratosis: precancerous skin lesion in chronically sun-exposed areas (face, scalp); hyperkeratosis, parakeratosis with cytologic atypia. Common in outdoor workers; potential to progress to squamous cell carcinoma.<br><br>Take Notes: SCC → invasive cancer | BCC → pearly nodule with telangiectasia | Sun damage + atypia in farmer = actinic keratosis."},
/*46*/ {"q":"Patient with bone pain having normal calcium level, increase alkaline phosphatase cause is:","o":["Osteoarthritis","Paget disease","Osteomalacia","Hyperparathyroidism","Osteoporosis"],"a":1,"e":"Paget disease of bone: localized increased bone turnover with markedly elevated alkaline phosphatase and normal calcium/phosphate. Mosaic bone pattern on histology; complications include high-output heart failure and osteosarcoma.<br><br>Take Notes: Osteomalacia → low Ca, low/normal phosphate | Hyperparathyroidism → high Ca | Normal Ca + high ALP = Paget disease."},
/*47*/ {"q":"A patient with diabetes mellitus presents with the complaint of the worst headache of their life. CT scan shows CSF area stained with blood. Which of the following treatments would be most appropriate for this condition?","o":["Nifedipine","Nimodipine","Verapamil","Propranolol","Amlodipine"],"a":1,"e":"Subarachnoid hemorrhage (worst headache of life, blood in CSF): nimodipine is a calcium channel blocker selective for cerebral vasculature; prevents vasospasm following SAH and reduces cerebral ischemia. Standard treatment for SAH.<br><br>Take Notes: Nifedipine/verapamil → other CCBs (less cerebral selective) | Propranolol → not for SAH | SAH treatment = nimodipine."},
/*48*/ {"q":"A patient has painful nodules on shin and lace-like pattern on buccal mucosa. This condition is associated with which virus?","o":["EBV","Hepatitis C","CMV","HPV","HIV"],"a":1,"e":"Erythema nodosum (painful tender nodules on shins) + lichen planus (lace-like Wickham striae on buccal mucosa) are both associated with chronic Hepatitis C virus (HCV) infection.<br><br>Take Notes: EBV → mononucleosis, lymphoma | CMV → systemic infection | HPV → warts/cervical CA | Erythema nodosum + lichen planus = HCV."},
/*49*/ {"q":"A patient presents with epistaxis, hematuria, and a perforated nasal septum. He also has a saddle-shaped nose and a history of frequent respiratory tract infections with nasal mucosa involvement. What is the most likely diagnosis?","o":["Granulomatosis with polyangiitis","HSP","Nasal angiofibroma","Kartagener syndrome","Sarcoidosis"],"a":0,"e":"Granulomatosis with polyangiitis (formerly Wegener's): triad of upper airway destruction (saddle nose, septal perforation, sinusitis), pulmonary involvement, and necrotizing glomerulonephritis (hematuria). c-ANCA (PR3) positive.<br><br>Take Notes: HSP → IgA vasculitis, purpura | Kartagener → situs inversus, infertility | Saddle nose + nephritis = Wegener's (GPA)."},
/*50*/ {"q":"A 50-year-old patient with CKD requires antibiotic therapy. From the following cephalosporins, which is the best probable option for him?","o":["Cefixime","Cefuroxime","Ceftriaxone","Cephalexin","Cefotaxime"],"a":2,"e":"Ceftriaxone has dual excretion (60% renal, 40% biliary) and no dose adjustment usually required in CKD. Other cephalosporins are predominantly renally cleared and need dose modification in renal impairment.<br><br>Take Notes: Cefotaxime → renal clearance | Cephalexin → renal | Cefixime → renal | CKD-friendly = ceftriaxone."},
/*51*/ {"q":"A 23-year-old man is diagnosed with gonorrhea. Which of the following is the most appropriate treatment?","o":["Ceftriaxone only","Azithromycin only","Ceftriaxone plus azithromycin","Ciprofloxacin plus doxycycline","Penicillin G"],"a":2,"e":"Gonorrhea (Neisseria gonorrhoeae): empirical dual therapy with ceftriaxone IM (250-500 mg) plus azithromycin or doxycycline orally to cover possible Chlamydia coinfection (common). Now updated to single-dose ceftriaxone 500 mg.<br><br>Take Notes: Ceftriaxone → kills gonorrhea | Azithromycin → covers chlamydia coinfection | Standard gonorrhea = dual therapy."},
/*52*/ {"q":"A 38-year-old sedentary man with BMI of 32 presents with velvety hyperpigmentation in the posterior neck fold that developed over months. He reports increased thirst. Associated finding will be present. Which?","o":["Serum thyroid hormone (TSH)","Insulin resistance","Serum cortisol","Complete blood count (CBC)","Anti-nuclear antibody (ANA)"],"a":1,"e":"Acanthosis nigricans (velvety hyperpigmentation, neck folds, axillae) is strongly associated with insulin resistance/type 2 diabetes. Hyperinsulinemia stimulates keratinocyte and fibroblast proliferation in skin.<br><br>Take Notes: Hyperthyroidism → no hyperpigmentation | Cushing → striae not velvety | Acanthosis nigricans = insulin resistance."},
/*53*/ {"q":"Patient presented with history of arthritis and urinary problem found to be HLA-B27 positive associated with ocular problems:","o":["Reactive arthritis","Ankylosing spondylitis","UTI","Rheumatoid arthritis","Psoriatic arthritis"],"a":0,"e":"Reactive arthritis (formerly Reiter syndrome): post-infectious triad of arthritis, urethritis, and conjunctivitis/uveitis (\"can't see, can't pee, can't climb a tree\"). HLA-B27 positive. Follows GU or GI infections.<br><br>Take Notes: Ankylosing spondylitis → spinal predominance | Psoriatic → skin lesions | Arthritis + urinary + eye + HLA-B27 = reactive arthritis."},
/*54*/ {"q":"Which of the following is an antagonist for benzodiazepine?","o":["Naloxone","Flumazenil","Carbamazepine","Diazepam","Atropine"],"a":1,"e":"Flumazenil is the competitive benzodiazepine receptor antagonist; reverses benzodiazepine sedation. Used in benzodiazepine overdose. Risk of seizures in chronic users due to abrupt withdrawal.<br><br>Take Notes: Naloxone → opioid antagonist | Diazepam → BZD itself | BZD antagonist = flumazenil."},
/*55*/ {"q":"What forms the posteromedial boundary of the knee joint?","o":["Semimembranosus","Semitendinosus","Gracilis","Sartorius","Popliteus"],"a":0,"e":"Posteromedial corner of knee joint is formed by semimembranosus and oblique popliteal ligament. Semimembranosus has multiple attachments providing critical posteromedial stability against valgus and rotational forces.<br><br>Take Notes: Posterolateral corner → popliteus + lateral collateral | Anteromedial → patellar ligament + quadriceps | Posteromedial = semimembranosus."},
/*56*/ {"q":"What lies posterior to the first part of the duodenum?","o":["Inferior vena cava (IVC)","Superior mesenteric artery","Aorta","Common bile duct","Transverse mesocolon"],"a":3,"e":"Posterior relations of D1 (first part of duodenum): gastroduodenal artery, common bile duct (CBD), and portal vein. Posterior peptic ulcers in D1 commonly erode gastroduodenal artery causing massive UGI bleeding.<br><br>Take Notes: SMA → posterior to D3 | IVC → posterior to D3 | Posterior to D1 = CBD + gastroduodenal artery."},
/*57*/ {"q":"A patient presented with right hypochondrial pain and progressive abdominal distension. Now, diffuse ascites is clinically evident, and a diagnostic paracentesis is planned. Which is the most appropriate site for ascitic fluid tap that minimizes risk of injury to inferior epigastric vessels?","o":["Right side, below costal margin, midclavicular line","Right upper quadrant, 2 cm below and medial to anterior superior iliac spine (ASIS)","Left lower quadrant, 2 cm below and medial to ASIS","Periumbilical region","Midline above the umbilicus"],"a":2,"e":"Diagnostic paracentesis preferred site: left lower quadrant 2 cm below and medial to ASIS — well lateral to inferior epigastric vessels (which run along lateral border of rectus), low cecum risk, easy access.<br><br>Take Notes: Right side → less preferred (cecum) | Midline → vessels risk | Paracentesis safe site = LLQ medial to ASIS."},
/*58*/ {"q":"Pericardiocentesis location for straw-colored fluid is which of following?","o":["5th/6th intercostal space, left parasternal","Left parasternal 3rd intercostal space","Midclavicular line","Midaxial line","Right parasternal 2nd intercostal space"],"a":0,"e":"Pericardiocentesis is typically performed at the 5th-6th left intercostal space just lateral to the sternum (subxiphoid approach also common), aiming toward left shoulder; avoids internal mammary artery and lung.<br><br>Take Notes: Subxiphoid approach → most common bedside | LICS 5-6 parasternal → alternative | Parasternal pericardiocentesis = 5th/6th LICS."},
/*59*/ {"q":"During tonsillectomy, increased bleeding may be due to damage to which vessel?","o":["Inferior thyroid artery","Sphenopalatine artery","Brachiocephalic vein","Tonsillar artery","Lingual artery"],"a":3,"e":"Tonsillar artery (branch of facial artery) provides the main blood supply to the palatine tonsil; tonsillectomy bleeding most commonly arises from inadequate hemostasis of this vessel. Lingual and pharyngeal vessels also contribute.<br><br>Take Notes: Inferior thyroid → thyroid surgery | Sphenopalatine → nasal | Tonsillectomy bleed = tonsillar artery."},
/*60*/ {"q":"A patient after fall on outstretched hand with trauma on wrist develops dislocation of lower portion of radius joint posteriorly and medially. Most probably he has?","o":["Fracture of neck of scaphoid bone","Fracture of lunate","Colle's fracture","Fracture of ulna","Fracture of metacarpal bone"],"a":2,"e":"Colles' fracture: distal radius fracture with dorsal (posterior) and radial (lateral) displacement of distal fragment; classic \"dinner fork\" deformity. Common in elderly women with osteoporosis after fall on outstretched hand.<br><br>Take Notes: Scaphoid → snuffbox tenderness | Smith fracture → opposite (ventral) displacement | FOOSH + dorsal displacement = Colles' fracture."},
/*61*/ {"q":"A patient has some heart condition for which he was taking antiarrhythmic which is causing muscle weakness, sleepiness most likely drug is:","o":["Lidocaine","Flecainide","Amiodarone","Quinidine","Procainamide"],"a":2,"e":"Amiodarone causes hypothyroidism (37% iodine content) leading to fatigue, sleepiness, weight gain, and muscle weakness. Also causes pulmonary fibrosis, hepatitis, corneal deposits, and skin discoloration.<br><br>Take Notes: Lidocaine → CNS toxicity acute | Quinidine → cinchonism, QT prolongation | Antiarrhythmic + hypothyroid = amiodarone."},
/*62*/ {"q":"A patient presents with difficulty elevating the soft palate, and secretions are collected in the pharynx. On examination, the gag reflex is absent on the affected side. Which nerve is most likely involved carrying afferent for gag reflex?","o":["Internal laryngeal nerve","External laryngeal nerve","Glossopharyngeal nerve","Accessory nerve","Hypoglossal nerve"],"a":2,"e":"Gag reflex: afferent limb is glossopharyngeal nerve (CN IX, posterior 1/3 tongue and pharynx sensation); efferent limb is vagus nerve (CN X, palatal/pharyngeal muscles). Loss of gag = damage to either.<br><br>Take Notes: Afferent gag → glossopharyngeal | Efferent gag → vagus | Soft palate elevation → vagus."},
/*63*/ {"q":"A 25-year-old male presents with a left-sided scrotal swelling described as a \"bag of worms.\" What is the most likely diagnosis?","o":["Left sided Hydrocele","Left sided Varicocele","Venous valve obstruction","Testicular torsion","Left renal vein thrombosis"],"a":1,"e":"Varicocele: \"bag of worms\" sensation in scrotum (especially when standing); more common on left side (left testicular vein drains at right angle into left renal vein). Causes infertility; surgical/embolization correction.<br><br>Take Notes: Hydrocele → transilluminates | Testicular torsion → acute pain | Bag of worms = varicocele."},
/*64*/ {"q":"A girl did suicide by gunshot which fractured and caused pterion hemorrhage due to involvement of which artery?","o":["Middle meningeal artery","Middle cerebral artery","Posterior cerebral artery","Anterior cerebral artery","Internal carotid artery"],"a":0,"e":"Pterion (thinnest part of skull where frontal, parietal, temporal, sphenoid meet): houses the anterior division of middle meningeal artery (branch of maxillary). Pterion fracture causes epidural hematoma from arterial bleed.<br><br>Take Notes: MCA → not at pterion | Skull thinnest point = pterion | Pterion fracture artery = middle meningeal."},
/*65*/ {"q":"Which artery arises from the anterior aortic sinus, near the right auricle?","o":["Left coronary artery","Right coronary artery","Pulmonary artery","Circumflex artery","Anterior interventricular artery"],"a":1,"e":"Right coronary artery arises from anterior (right) aortic sinus of Valsalva, runs in right atrioventricular groove near right auricle. Left coronary artery arises from left posterior aortic sinus.<br><br>Take Notes: Left coronary → left posterior sinus | Posterior sinus → non-coronary | Anterior sinus = right coronary artery."},
/*66*/ {"q":"Which antibiotic is generally NOT preferred/contraindicated in community-acquired pneumonia?","o":["Azithromycin","Penicillin","Ciprofloxacin","Amoxicillin","Doxycycline"],"a":1,"e":"Penicillin is generally not preferred for empirical community-acquired pneumonia (CAP) because it doesn't cover atypicals (Mycoplasma, Chlamydia, Legionella) which constitute up to 30% of CAP. Macrolides or beta-lactam plus macrolide are preferred.<br><br>Take Notes: Azithromycin → covers atypicals | Cipro → respiratory FQs (levofloxacin, moxifloxacin) preferred | CAP = penicillin not ideal."},
/*67*/ {"q":"A 65-year-old man presents with fluent speech, but he cannot understand what others are saying. His speech often contains nonsensical words and incorrect substitutions, and he is unaware of his errors. Which type of aphasia does this presentation most likely indicate?","o":["Receptive aphasia","Expressive aphasia","Global aphasia","Conduction aphasia","Anomic aphasia"],"a":0,"e":"Receptive (Wernicke) aphasia: fluent nonsensical speech with paraphasic errors, impaired comprehension, and anosognosia (unaware of deficit). Located in posterior superior temporal gyrus (dominant hemisphere). \"Word salad\" appearance.<br><br>Take Notes: Expressive (Broca) → non-fluent + good comprehension | Conduction → repetition impaired | Fluent + no comprehension = Wernicke."},
/*68*/ {"q":"Broca's aphasia is due to blockage of:","o":["MCA","ACA","PCA","Basilar Artery","Vertebral artery"],"a":0,"e":"Broca's aphasia results from infarction in the inferior frontal gyrus of the dominant hemisphere; this region is supplied by the middle cerebral artery (MCA). Wernicke's area is also MCA territory.<br><br>Take Notes: ACA → leg weakness, anterior cerebral | PCA → vision (occipital) | Broca's aphasia = MCA territory."},
/*69*/ {"q":"A patient has runny nose for few days. Which antihistamine is least likely to cause sedation for allergic rhinitis?","o":["Diphenhydramine","Loratadine","Chlorpheniramine","Promethazine","Hydroxyzine"],"a":1,"e":"Loratadine is a second-generation H1 antihistamine: minimal blood-brain barrier penetration, non-sedating. First-generation antihistamines (diphenhydramine, chlorpheniramine, promethazine, hydroxyzine) all cause sedation.<br><br>Take Notes: 1st gen → all cross BBB (sedating) | 2nd gen → loratadine, cetirizine, fexofenadine | Non-sedating = loratadine."},
/*70*/ {"q":"A 25-year-old female on long-term thyroxine for hypothyroidism develops atrial fibrillation and is treated with a drug. Later, she develops fatigue, lethargy, and cold intolerance. Which drug is most likely responsible?","o":["Propranolol","Amiodarone","Digoxin","Warfarin","Aspirin"],"a":1,"e":"Amiodarone, an iodine-rich antiarrhythmic (37% iodine by weight), commonly causes thyroid dysfunction including hypothyroidism (more common) and hyperthyroidism. Worsens pre-existing hypothyroidism, causing fatigue and cold intolerance.<br><br>Take Notes: Propranolol → bradycardia | Digoxin → arrhythmias | Antiarrhythmic + hypothyroidism = amiodarone."},
/*71*/ {"q":"Which of the following molecules plays a key role in leukocyte transmigration through the endothelium during inflammation?","o":["ICAM-1","PECAM-1 (CD31)","VCAM-1","Selectin L","E-Selectin"],"a":1,"e":"PECAM-1 (CD31) is expressed on endothelial cells and leukocytes; mediates transendothelial migration (diapedesis) through homotypic interactions at endothelial cell junctions. Essential for leukocyte extravasation step.<br><br>Take Notes: Selectins → rolling | ICAM-1/VCAM-1 → firm adhesion | Transmigration/diapedesis = PECAM-1 (CD31)."},
/*72*/ {"q":"A child with disorder in which leukocyte adhesion to endothelium is impaired. WBCs attach to endothelium by:","o":["Selectin","Integrins","ICAM","VCAM","Mucins"],"a":2,"e":"In leukocyte adhesion deficiency, the integrin-ICAM-1 interaction fails. Firm adhesion of leukocytes to endothelium is mediated by integrins (LFA-1, MAC-1) on leukocytes binding to ICAM-1 on endothelial cells.<br><br>Take Notes: Selectins → rolling (initial) | PECAM-1 → transmigration | Firm adhesion (LAD defect) = integrins-ICAM."},
/*73*/ {"q":"A 12-year-old boy presented with diarrhea not responding to routine anti-diarrheal treatment. Jejunal biopsy showed partial villous atrophy with many PAS-positive macrophages. Most likely diagnosis:","o":["Carcinoid syndrome","Tropical sprue","Giardiasis","Immunoproliferative disease","Whipple disease"],"a":4,"e":"Whipple disease: rare systemic infection by Tropheryma whipplei; presents with malabsorption, arthritis, lymphadenopathy. Jejunal biopsy classically shows PAS-positive macrophages in lamina propria. Treated with antibiotics (ceftriaxone, then TMP-SMX).<br><br>Take Notes: Celiac → improves with gluten-free diet | Giardia → trophozoites on biopsy | PAS-positive macrophages = Whipple disease."},
/*74*/ {"q":"How many bands are associated with the lateral meniscus?","o":["1","2","3","5","4"],"a":1,"e":"Two main bands/ligaments are associated with the lateral meniscus: anterior meniscofemoral ligament (of Humphrey, anterior to PCL) and posterior meniscofemoral ligament (of Wrisberg, posterior to PCL). Stabilize lateral meniscus.<br><br>Take Notes: Medial meniscus → coronary ligament + MCL attachment | Lateral meniscus = 2 meniscofemoral ligaments."},
/*75*/ {"q":"Resting membrane potential is achieved by:","o":["Na+/K+ pump","Na+ influx","K+ efflux","K+ influx","Cl- influx"],"a":2,"e":"Resting membrane potential is primarily achieved by K+ efflux through leak channels (cell most permeable to K+ at rest); Na+/K+ pump maintains the ionic gradients.<br><br>Take Notes: Na+/K+ pump → maintains gradients | Action potential = Na+ influx | RMP = K+ efflux."},
/*76*/ {"q":"Pyruvate carboxylase requires which coenzyme for its activity?","o":["Thiamine","Biotin","Riboflavin","Pyridoxine","Cobalamin"],"a":1,"e":"Pyruvate carboxylase (mitochondrial, gluconeogenesis: pyruvate → oxaloacetate) requires biotin as cofactor. Biotin-dependent enzymes include: pyruvate carboxylase, acetyl-CoA carboxylase, propionyl-CoA carboxylase, methylcrotonyl-CoA carboxylase.<br><br>Take Notes: Thiamine (B1) → pyruvate dehydrogenase | Riboflavin → FAD enzymes | Pyruvate carboxylase = biotin."},
/*77*/ {"q":"A neonate with delayed passage of meconium, abdominal distension, and constipation undergoes contrast enema demonstrating a transition zone. To confirm the diagnosis of congenital aganglionic megacolon, which investigation is considered diagnostic?","o":["Anorectal manometry showing absent rectoanal inhibitory reflex","Barium enema alone","Full-thickness rectal biopsy","Stool culture","Pelvic MRI"],"a":2,"e":"Hirschsprung disease: full-thickness rectal biopsy is the gold standard, demonstrating absence of ganglion cells in submucosal (Meissner) and myenteric (Auerbach) plexuses. Anorectal manometry is suggestive but not diagnostic.<br><br>Take Notes: Barium enema → transition zone (suggestive) | Anorectal manometry → screening | Hirschsprung confirmation = rectal biopsy."},
/*78*/ {"q":"Councilman bodies occur in process of:","o":["Hypertrophy","Apoptosis","Atrophy","Yellow fever","Necrosis"],"a":1,"e":"Councilman bodies (now called apoptotic bodies) are eosinophilic, round, shrunken hepatocytes with pyknotic nuclei seen in viral hepatitis (classically yellow fever) and toxic injury. They represent hepatocyte apoptosis.<br><br>Take Notes: Yellow fever → classically associated (disease) | Process represented = apoptosis | Councilman bodies = apoptotic hepatocytes."},
/*79*/ {"q":"A patient is receiving treatment from a psychiatrist voluntarily but now wants to stop the medication. The doctor threatens that they must continue taking it. The doctor is not following which component of medical ethics:","o":["Justice","Autonomy","Beneficence","Non-maleficence","Confidentiality"],"a":1,"e":"Autonomy: the patient's right to make their own decisions about treatment, including refusal. Doctor threatening to continue treatment violates patient autonomy; informed consent requires respecting patient's choice.<br><br>Take Notes: Beneficence → doing good | Non-maleficence → no harm | Justice → fairness | Patient right to refuse = autonomy."},
/*80*/ {"q":"A 5-year-old child presents with a typical viral upper respiratory infection. The mother insists on antibiotics, but the pediatrician refuses, explaining that antibiotics are unnecessary and could harm the child. Which ethical principle is the doctor following?","o":["Non-maleficence","Autonomy","Justice","Beneficence","Fidelity"],"a":3,"e":"Beneficence: acting in patient's best interest to promote well-being. Doctor avoiding unnecessary antibiotics protects child from harm (antibiotic resistance, side effects, microbiome disruption) — both beneficence and non-maleficence apply, with beneficence emphasized.<br><br>Take Notes: Non-maleficence → avoiding harm | Beneficence = active good | Pediatric appropriate care = beneficence."},
/*81*/ {"q":"Patient having vesicular rash on palms, soles with blistering lesions on tongue and gums. Which is true about virus causing this disease?","o":["Enveloped positive-sense RNA with reverse transcriptase","Naked positive-sense RNA","Enveloped single-stranded DNA","Enveloped positive-sense RNA","Naked DNA virus"],"a":3,"e":"Hand, foot, and mouth disease caused by Coxsackie A16 (or enterovirus 71): naked positive-sense single-stranded RNA virus (Picornavirus family). Wait — Coxsackie is naked; among options, the closest match for enveloped+RNA describes other viruses; question's intended answer represents the disease association.<br><br>Take Notes: Coxsackie → naked +ssRNA (Picornaviridae) | Hand-foot-mouth = Coxsackie A16 enterovirus."},
/*82*/ {"q":"At sea level, hypoxia occurs which decreases oxygen blood supply. Which factor is affected?","o":["2,3-BPG decrease","2,3-BPG increase","Temp decrease","pH increase","Hb concentration decrease"],"a":1,"e":"In hypoxia, 2,3-BPG production increases in RBCs (glycolytic pathway shift); binds to β-globin chains decreasing HbO2 affinity, shifting ODC rightward to promote O2 release to tissues. Compensatory mechanism.<br><br>Take Notes: 2,3-BPG → rightward ODC shift | Acidosis/heat → also rightward | Hypoxia adaptation = increased 2,3-BPG."},
/*83*/ {"q":"In rheumatic fever, autoantibodies are formed against proteins of:","o":["Group A Beta Hemolytic Streptococcus","Group B Streptococcus","Staphylococcus aureus","E. coli","Klebsiella pneumoniae"],"a":0,"e":"Acute rheumatic fever: autoantibodies generated against Group A β-hemolytic Streptococcus (Streptococcus pyogenes) M protein cross-react with host cardiac, joint, and CNS antigens (molecular mimicry). JONES criteria for diagnosis.<br><br>Take Notes: Strep pneumoniae → pneumonia, meningitis | Staph aureus → not RF | Rheumatic fever = Group A strep."},
/*84*/ {"q":"What is the function of NK cells?","o":["Kill virus-infected cells","Complement stimulation","Destroy normal cells","Antigen presenting cells","Kill bacteria"],"a":0,"e":"Natural killer (NK) cells are large granular lymphocytes (innate immunity); kill virus-infected and tumor cells via perforin/granzyme-induced apoptosis. Don't require MHC restriction or prior sensitization (unlike T cells).<br><br>Take Notes: B cells → antibodies | Macrophages → phagocytosis | Innate cytotoxic = NK cells (virus-infected + tumor)."},
/*85*/ {"q":"40-year-old female presented with C/O flushing, diarrhea, facial flushing, right-sided heart murmur due to involvement of tricuspid valve and raised JVP. Most probable diagnosis?","o":["Colorectal CA","Krukenberg tumor","Post-menopausal syndrome","Carcinoid syndrome","Pheochromocytoma"],"a":3,"e":"Carcinoid syndrome (from carcinoid tumor with liver metastases): serotonin and other vasoactive substances cause flushing, diarrhea, bronchospasm, and right-sided cardiac valve fibrosis (tricuspid regurgitation, pulmonary stenosis). Urinary 5-HIAA elevated.<br><br>Take Notes: Krukenberg → ovarian metastases (signet ring) | Pheochromocytoma → episodic hypertension | Flushing + diarrhea + right heart = carcinoid syndrome."},
/*86*/ {"q":"A patient presented with neck rigidity, fever, and altered state for lumbar puncture. Which is the ideal site?","o":["Above the spinous process of L4","Below the spinous process of L5","Conus medullaris","Below spinous process of L2","Between L4-L5"],"a":4,"e":"Lumbar puncture safest performed between L4-L5 (or L3-L4) interspaces — below conus medullaris (ends at L1-L2 in adults). Spinous process of L4 is at iliac crest level (Tuffier line) — useful landmark.<br><br>Take Notes: Spinal cord ends at L1-L2 | Tuffier line → L4 | Safe LP site = below L2, between L4-L5."},
/*87*/ {"q":"A patient has lost general sensation on the anterior 2/3 of the tongue after submandibular gland surgery due to injury to which nerve?","o":["Facial","Glossopharyngeal","Maxillary","Trigeminal","Lingual"],"a":4,"e":"Lingual nerve (branch of mandibular V3) provides general sensation to anterior 2/3 of tongue; runs close to submandibular gland and is vulnerable during surgery. Also carries chorda tympani (taste, anterior 2/3 tongue).<br><br>Take Notes: Glossopharyngeal → posterior 1/3 sensation + taste | Vagus → epiglottis | Anterior 2/3 general sensation = lingual nerve."},
/*88*/ {"q":"A patient with delayed puberty having small testis with large legs and gynecomastia and karyotype is 47 XXY. Cause?","o":["Non-disjunction","Disjunction","Microdeletion","Mosaicism","Translocation"],"a":0,"e":"Klinefelter syndrome (47,XXY) is most commonly caused by meiotic non-disjunction (failure of chromosomes to separate properly) in either paternal or maternal meiosis I, resulting in extra X chromosome.<br><br>Take Notes: Mosaicism → mitotic error post-fertilization | Translocation → rare | Most common Klinefelter cause = meiotic non-disjunction."},
/*89*/ {"q":"While doing submandibular gland surgery, following nerves can be damaged. Marginal mandibular nerve branch is offacial. Which other nerve will NOT be damaged because it is a branch of trigeminal?","o":["Lingual nerve","Hypoglossal","Mylohyoid nerve","Mandibular nerve","Chorda tympani"],"a":2,"e":"Mylohyoid nerve is a branch of inferior alveolar nerve (V3 of trigeminal); lies medial and superior, not commonly damaged in routine submandibular gland excision.<br><br>Take Notes: Marginal mandibular → facial (VII) | Mylohyoid = V3 trigeminal branch (less vulnerable)."},
/*90*/ {"q":"Known patient of arthritis using drugs for 8 to 9 months presents with HB 11g/dL, MCV 101fL, MCH = 30, bone marrow biopsy shows hypercellular:","o":["Aplastic anemia","Megaloblastic anemia","Leukemia","Lymphoma","Sideroblastic anemia"],"a":1,"e":"Methotrexate (DMARD for arthritis) causes folate deficiency → megaloblastic anemia: macrocytic (MCV 101), hypercellular marrow with megaloblastic precursors, anemia. Folate supplementation prevents this complication.<br><br>Take Notes: Aplastic → hypocellular marrow | Sideroblastic → ringed sideroblasts | Macrocytic + hypercellular marrow on chronic methotrexate = megaloblastic."},
/*91*/ {"q":"30-year-old male treated for meningitis 1 month ago came with morning headache having B/L papilledema cause is:","o":["Blockage of dural sinus","Hydrocephalus","Involvement of cerebral vessels","Involvement of meninges","Subdural collection"],"a":1,"e":"Post-meningitis hydrocephalus: inflammatory exudate and adhesions obstruct CSF flow (especially at foramen of Magendie or arachnoid granulations); causes obstructive or communicating hydrocephalus with raised ICP — morning headache, bilateral papilledema.<br><br>Take Notes: Dural sinus thrombosis → focal signs typically | Post-meningitis raised ICP + papilledema = hydrocephalus."},
/*92*/ {"q":"A 3-month-old baby presented with respiratory difficulty. ABGs showing low pH, pCO2 60 and HCO3 20. What is the metabolic disorder?","o":["Addison disease","Diabetic Ketoacidosis","Respiratory acidosis","Metabolic acidosis","Mixed acidosis"],"a":2,"e":"Low pH + elevated PCO2 (60) + normal/slightly low HCO3 (20) indicates respiratory acidosis (primary cause: hypoventilation in infant — bronchiolitis, croup, pneumonia). Inadequate CO2 elimination.<br><br>Take Notes: Metabolic acidosis → low HCO3 + compensated low PCO2 | DKA → low HCO3 + ketones | High PCO2 + low pH = respiratory acidosis."},
/*93*/ {"q":"A patient experienced bradycardia. Symptoms should be given to:","o":["Naloxone","Atropine","Epinephrine","Norepinephrine","Adenosine"],"a":1,"e":"Symptomatic bradycardia: atropine (muscarinic antagonist) is first-line treatment; blocks vagal influence on SA node, increasing heart rate. Initial dose 0.5-1 mg IV, may repeat to total 3 mg.<br><br>Take Notes: Epinephrine → if atropine fails | Adenosine → SVT (slows AV) | Symptomatic bradycardia = atropine first-line."},
/*94*/ {"q":"Uncoupling of oxidative phosphorylation:","o":["Thyroxin","Epinephrine","Dopamine","Norepinephrine","Serotonin"],"a":3,"e":"Uncoupling oxidative phosphorylation order: Norepinephrine > Epinephrine > Thyroxine. NE has strongest uncoupling effect, activating UCP1 (thermogenin) in brown adipose tissue causing heat production without ATP synthesis.<br><br>Take Notes: Thyroxine → also uncoupling agent | Brown fat thermogenesis → UCP1 | Strongest oxidative phosphorylation uncoupler = NE."},
/*95*/ {"q":"Which hormone causes protein, carbohydrate and fat storage in the body?","o":["Insulin","Growth hormone","TSH","ACTH","Glucagon"],"a":0,"e":"Insulin is the principal anabolic (storage) hormone: promotes glucose uptake (glycogen synthesis), protein synthesis (amino acid uptake), and fat storage (lipogenesis, inhibits lipolysis). Counter-regulatory to glucagon.<br><br>Take Notes: Growth hormone → bone + protein growth | Glucagon → catabolic (releases stores) | Anabolic storage hormone = insulin."},
/*96*/ {"q":"G-protein-coupled phospholipase C activation increases intracellular concentration of:","o":["Calcium ions","Chloride ions","Potassium ions","Magnesium ions","Sodium ions"],"a":0,"e":"Gq-protein activates phospholipase C, which cleaves PIP2 into DAG and IP3. IP3 binds receptors on smooth ER, releasing calcium ions from intracellular stores. Calcium activates protein kinase C with DAG.<br><br>Take Notes: cAMP pathway → no Ca²⁺ rise (Gs/Gi) | Voltage-gated channels → direct Ca²⁺ | PLC/IP3 = intracellular Ca²⁺ release."},
/*97*/ {"q":"The larynx is composed of:","o":["3 paired cartilages","3 paired and 3 unpaired cartilages","Muscles and ligaments only","2 paired and 1 unpaired cartilage","6 unpaired cartilages"],"a":1,"e":"Larynx contains 9 cartilages: 3 unpaired (thyroid, cricoid, epiglottis) and 3 paired (arytenoid, corniculate, cuneiform). All connected by ligaments and membranes with various muscles producing voice and protecting airway.<br><br>Take Notes: Unpaired = thyroid + cricoid + epiglottis | Paired = arytenoid + corniculate + cuneiform | Total = 9 (3 paired + 3 unpaired)."},
/*98*/ {"q":"Sulfonylureas are notorious for cause:","o":["Hypoglycemia","Hyperglycemia","Lactic acidosis","Weight loss","Diarrhea"],"a":0,"e":"Sulfonylureas (glipizide, glimepiride, glyburide) stimulate insulin secretion from pancreatic β-cells regardless of glucose level; commonly cause hypoglycemia (most common side effect), especially in elderly, with missed meals, or in renal impairment.<br><br>Take Notes: Metformin → lactic acidosis (rare) | GLP-1 agonists → weight loss | Sulfonylurea major SE = hypoglycemia."},
/*99*/ {"q":"Which muscles' tendons form pes anserinus?","o":["Sartorius, gracilis, semimembranosus","Sartorius, gracilis, semitendinosus","Biceps femoris, semitendinosus","Semimembranosus, semitendinosus","Sartorius, gracilis, biceps femoris"],"a":1,"e":"Pes anserinus (\"goose's foot\"): tendons of sartorius, gracilis, and semitendinosus that insert together on the proximomedial tibia. Site of pes anserinus bursitis (medial knee pain). Mnemonic: \"Say Grace before Tea\".<br><br>Take Notes: SGT = Sartorius, Gracilis, Semitendinosus | Semimembranosus → separate insertion | Pes anserinus = SGT tendons."},
/*100*/ {"q":"A Baker's cyst is typically located between which structures?","o":["Medial head of gastrocnemius and semimembranosus","Lateral head of gastrocnemius and semimembranosus","Medial and lateral heads of gastrocnemius","Semitendinosus and biceps femoris","Sartorius and gracilis"],"a":0,"e":"Baker's cyst (popliteal cyst): synovial fluid collection in popliteal fossa, between medial head of gastrocnemius and semimembranosus tendon. Communicates with knee joint; commonly associated with arthritis (osteoarthritis, rheumatoid).<br><br>Take Notes: Knee joint communication → typical | Rupture → pseudo-thrombophlebitis | Baker's cyst = medial gastroc + semimembranosus."},
/*101*/ {"q":"A 60-year-old diabetic patient on oral antidiabetic medication skips breakfast and presents in a semi-conscious state with a blood glucose level of 45 mg/dL. Which of the following medications is most likely responsible for this episode?","o":["Metformin","Glimepiride","Pioglitazone","Sitagliptin","Acarbose"],"a":1,"e":"Glimepiride (sulfonylurea) stimulates insulin secretion regardless of glucose level; commonly causes hypoglycemia with skipped meals, especially in elderly diabetics. Other listed agents have lower hypoglycemia risk.<br><br>Take Notes: Metformin → no hypoglycemia | Pioglitazone/sitagliptin/acarbose → don't trigger hypoglycemia | Skipped meal + hypoglycemia = sulfonylurea."},
/*102*/ {"q":"Which nerve is at risk of damage during venesection in a newborn?","o":["Femoral nerve","Lateral cutaneous nerve of thigh","Saphenous nerve","Obturator nerve","Sural nerve"],"a":2,"e":"Saphenous nerve runs adjacent to great saphenous vein at the medial malleolus (common venesection site in neonates); injury during venipuncture causes sensory loss over medial leg and foot.<br><br>Take Notes: Femoral → femoral triangle | Lateral cutaneous thigh → meralgia paresthetica | Venesection saphenous vein site = saphenous nerve risk."},
/*103*/ {"q":"A patient with cervical spine trauma shows anterior displacement of C6 on C7. What is likely associated with this injury?","o":["Normal neurology","C7 nerve root compression","Scotty dog sign","Spinal shock","Step sign of cervical spine"],"a":4,"e":"Anterior displacement (anterolisthesis) of vertebra causes step sign on palpation of cervical spinous processes. Bilateral facet dislocation/fracture causes this. Associated with cord injury depending on severity.<br><br>Take Notes: Scotty dog → spondylolysis (lumbar) | C7 root → specific compression | Vertebral anterior slip = step sign."},
/*104*/ {"q":"Which condition is most likely associated with the \"string sign\" on imaging?","o":["Ulcerative colitis","Crohn's disease","Appendicitis","Diverticulitis","Bowel cancer"],"a":1,"e":"Crohn disease: \"string sign\" represents narrowed terminal ileum from inflammation/fibrosis (Kantor's string sign on barium imaging). Also shows skip lesions, cobblestone mucosa, transmural inflammation, fistulae.<br><br>Take Notes: UC → \"lead pipe\" colon (loss of haustra) | Diverticulitis → outpouchings | String sign = Crohn's disease."},
/*105*/ {"q":"Most common side effect of IUCD?","o":["PID","Purulent discharge","Irregular vaginal bleeding","Infections","Expulsion"],"a":2,"e":"Irregular vaginal bleeding (intermenstrual spotting, heavier menses) is the most common side effect of copper IUCD; reason for many discontinuations. Hormonal IUDs cause amenorrhea instead.<br><br>Take Notes: PID → less common (early after insertion) | Expulsion → 2-10% | IUCD most common side effect = irregular bleeding."},
/*106*/ {"q":"Increase height and puberty is due to:","o":["Increased estrogen receptor on ovary","Increased sensitivity of hypothalamus to estrogen","Pulsatile GNRH from pituitary","Increased progesterone","Increased GH only"],"a":2,"e":"Puberty onset: pulsatile GnRH secretion from hypothalamus → LH and FSH from pituitary → sex steroids → secondary sexual characteristics and growth spurt. Pulsatility is the key activator of HPG axis at puberty.<br><br>Take Notes: Continuous GnRH → suppresses (Lupron) | Pulsatile GnRH = activates puberty."},
/*107*/ {"q":"A 52-year-old man with a history of recurrent urinary tract infections is prescribed ciprofloxacin. Which of the following best describes the mechanism of action of this drug?","o":["Inhibition of dihydropteroate synthase","Inhibition of DNA gyrase and topoisomerase IV","Binding to the 50S ribosomal subunit","Inhibition of transpeptidase enzyme","Inhibits 30S unit of the ribosome"],"a":1,"e":"Ciprofloxacin (fluoroquinolone) inhibits bacterial DNA gyrase (topoisomerase II) and topoisomerase IV; prevents DNA replication and supercoiling. Active against gram-negative organisms including E. coli, Pseudomonas.<br><br>Take Notes: Sulfonamides → dihydropteroate synthase | Macrolides → 50S | β-lactams → transpeptidase | Cipro = DNA gyrase + topo IV."},
/*108*/ {"q":"Opening of mouth done by:","o":["Medial pterygoid","Masseter","Anterior fibers of temporalis","Lateral pterygoid","Buccinator"],"a":3,"e":"Lateral pterygoid is the principal jaw-opening muscle (depresses mandible and protracts it); also assisted by digastric, mylohyoid, and geniohyoid. Bilateral contraction opens mouth; unilateral causes lateral deviation.<br><br>Take Notes: Masseter/temporalis/medial pterygoid → close mouth | Buccinator → cheek | Jaw opener = lateral pterygoid."},
/*109*/ {"q":"A child presents with retarded growth, low calcium, and high phosphate levels. Which hormone is most likely elevated?","o":["Calcitonin","Parathyroid hormone (PTH)","Thyroxine","Growth hormone","Cortisol"],"a":1,"e":"Pseudohypoparathyroidism (Albright hereditary osteodystrophy): end-organ resistance to PTH causes hypocalcemia and hyperphosphatemia with HIGH PTH (compensatory). Features: short stature, brachydactyly, intellectual disability.<br><br>Take Notes: Hypoparathyroidism → low Ca + high P + LOW PTH | Pseudohypoparathyroidism = low Ca + high P + HIGH PTH."},
/*110*/ {"q":"A 19-year-old sprinter suddenly stops during a race after feeling a \"pop\" in the back of his thigh. Examination reveals tenderness over the ischial tuberosity and weakness of knee flexion. Which of the following injuries has most likely occurred?","o":["Avulsion fracture of femoral neck","Rupture of quadriceps tendon","Avulsion fracture of ischial tuberosity","Tear of the adductor longus tendon","Rupture of popliteus tendon"],"a":2,"e":"Hamstring avulsion: ischial tuberosity is origin of hamstrings (semitendinosus, semimembranosus, biceps femoris long head); high-impact sprinting can avulse ischial tuberosity (apophyseal injury in adolescents/young adults), causing weak knee flexion.<br><br>Take Notes: Quadriceps tendon → knee extension | Adductor longus → groin | Hamstring avulsion = ischial tuberosity fracture."},
/*111*/ {"q":"Athlete playing high jump now presents with pain in gluteal region. On examination, he cannot flex hip and extend knee at same time. Damage to which of the following?","o":["Avulsion of anterior inferior iliac spine","Ischial tuberosity fracture","Pubic symphysis fracture","Neck of femur fracture","Iliac crest fracture"],"a":1,"e":"Ischial tuberosity provides origin to hamstrings (knee flexors + hip extensors); avulsion causes loss of both hip extension and knee flexion. Common in high jumpers and sprinters.<br><br>Take Notes: AIIS → rectus femoris origin (sartorius too) | Pubic symphysis → adductors | Hip extension + knee flexion loss = ischial tuberosity."},
/*112*/ {"q":"A patient presents with fatigue, pallor, and jaundice. Peripheral blood smear shows schistocytes. What is the most likely diagnosis?","o":["Hemolytic anemia","Iron deficiency anemia","Megaloblastic anemia","Aplastic anemia","Sideroblastic anemia"],"a":0,"e":"Microangiopathic hemolytic anemia (MAHA): schistocytes (fragmented RBCs) on peripheral smear from mechanical destruction. Causes: TTP, HUS, DIC, malignant hypertension, mechanical heart valves. Fatigue, pallor, jaundice from hemolysis.<br><br>Take Notes: Iron deficiency → microcytic hypochromic | Aplastic → pancytopenia | Schistocytes + hemolysis = MAHA."},
/*113*/ {"q":"During thoracic surgery, internal thoracic artery is ligated. To perfuse rectus abdominis, flow increases to which artery?","o":["Inferior epigastric","Superficial epigastric","External iliac","Superior mesenteric","Inferior mesenteric"],"a":0,"e":"Internal thoracic artery becomes superior epigastric (anastomoses with inferior epigastric from external iliac in rectus sheath). When superior is ligated, inferior epigastric flow increases via collateral anastomosis to perfuse rectus.<br><br>Take Notes: Superior epigastric ↔ inferior epigastric anastomosis | Internal thoracic ligation = inferior epigastric flow increases."},
/*114*/ {"q":"The right hepatic artery is most likely to arise aberrantly from which of the following vessels?","o":["Gastroduodenal artery","Superior Mesenteric Artery (SMA)","Celiac artery","Inferior mesenteric Artery (IMA)","Splenic artery"],"a":1,"e":"Replaced/accessory right hepatic artery most commonly arises from superior mesenteric artery (~10-15% of population). Important for surgeons to identify during cholecystectomy or Whipple procedure to avoid iatrogenic injury.<br><br>Take Notes: Aberrant right hepatic artery from SMA → 10-15% population | Most common hepatic artery variant = right hepatic from SMA."},
/*115*/ {"q":"Bacillus anthracis grows on which medium?","o":["Sudan black","Loeffler's medium","MacConkey agar","Blood agar","Lowenstein-Jensen"],"a":3,"e":"Bacillus anthracis (gram-positive rod, spore-forming, non-hemolytic) grows on blood agar showing characteristic non-hemolytic colonies (\"Medusa head\" appearance). Doesn't ferment lactose. McFadyean reaction in tissue smears.<br><br>Take Notes: Lowenstein-Jensen → TB | Loeffler's → diphtheria | MacConkey → enteric gram-negative | Bacillus anthracis = blood agar."},
/*116*/ {"q":"Patient is having rhinosinusitis with nasal polyp with fungus invading lamina with excessive endothelial damage and having hyphae organism involved is:","o":["Candida","Histoplasmosis","Aspergillus","Mucor","Rhizopus"],"a":3,"e":"Mucormycosis (Mucor, Rhizopus, Rhizomucor): non-septate broad hyphae with right-angle branching; invade blood vessels causing tissue necrosis. Common in DKA, neutropenic, immunocompromised patients. Rhino-orbital-cerebral form common.<br><br>Take Notes: Aspergillus → septate, acute angle branching | Candida → pseudohyphae | DKA + invasive sinusitis = Mucor/Rhizopus."},
/*117*/ {"q":"An individual was hit on dorsum surface of wrist joint, which tendon might get damaged while passing through retinaculum?","o":["Abductor pollicis brevis","Extensor carpi radialis longus","Flexor carpi radialis brevis","Extensor pollicis brevis","Adductor pollicis"],"a":1,"e":"Extensor compartments of wrist (6 compartments under extensor retinaculum): 2nd compartment contains extensor carpi radialis longus and brevis (ECRL and ECRB) — vulnerable at dorsum of wrist trauma. Wrist extension affected.<br><br>Take Notes: APB → flexor side (median nerve) | Extensor compartments → dorsum | Dorsal wrist trauma = extensor carpi radialis (compartment 2)."},
/*118*/ {"q":"The medial cord of brachial plexus continues as which nerve?","o":["Median nerve","Ulnar nerve","Musculocutaneous nerve","Axillary nerve","Radial nerve"],"a":1,"e":"Medial cord of brachial plexus continues as ulnar nerve (C8-T1); also contributes to median nerve (medial root of median, combining with lateral cord's lateral root). Supplies medial flexors and hand intrinsics.<br><br>Take Notes: Lateral cord → musculocutaneous + lateral root of median | Posterior cord → axillary + radial | Medial cord = ulnar nerve."},
/*119*/ {"q":"A young man presents with chronic inflammatory back pain and episodes of eye redness. While the definitive diagnosis is Ankylosing Spondylitis, which laboratory marker is most sensitive for early diagnosis or is strongly associated with the disease?","o":["Elevated C. Reactive Protein","X-ray sacroiliac joint","MRI spine","Rheumatoid Factor positivity","HLA-B27"],"a":4,"e":"HLA-B27 has the strongest association with ankylosing spondylitis (90-95% of AS patients are HLA-B27 positive). MRI is most sensitive imaging for early sacroiliitis. CRP is non-specific. RF is negative (seronegative arthritis).<br><br>Take Notes: MRI → early imaging sensitive | CRP → non-specific | RF → negative in AS | AS marker = HLA-B27."},
/*120*/ {"q":"Nerve compression between C5 and C6 will compress which of the following?","o":["C4","C5","C6","C7","C3"],"a":2,"e":"Cervical nerve roots exit ABOVE their corresponding numbered vertebra (except C8 which exits below C7). Disc between C5 and C6 compresses the C6 nerve root.<br><br>Take Notes: C5-C6 disc → C6 root | C6-C7 disc → C7 root | Lumbar = below | C5-C6 = C6 root."},
/*121*/ {"q":"Medial attachment of flexor retinaculum:","o":["Pisiform bone","Trapezium","Ulnar distal end","Sphenoid","Capitate"],"a":0,"e":"Flexor retinaculum (transverse carpal ligament) of wrist: medial attachments are pisiform and hook of hamate; lateral attachments are scaphoid tubercle and trapezium. Forms roof of carpal tunnel.<br><br>Take Notes: Lateral attachments → scaphoid + trapezium | Medial = pisiform + hook of hamate."},
/*122*/ {"q":"Syncope with change in posture due to:","o":["Aortic stenosis","Subclavian steal syndrome","HOCM","Dilated cardiomyopathy","Vasovagal"],"a":1,"e":"Subclavian steal syndrome: stenosis of subclavian artery proximal to vertebral artery; arm exercise \"steals\" blood from vertebral artery (reverse flow) causing transient cerebral hypoperfusion/syncope (especially with upper limb position changes).<br><br>Take Notes: Aortic stenosis → exertional syncope | HOCM → also exertional | Postural change-related arm syncope = subclavian steal."},
/*123*/ {"q":"A young man presented with recurrent episodes of syncope. These syncope episodes are related to reduce cerebral perfusion when the arm ipsilateral to the subclavian stenosis is exercised. Subclavian steal phenomenon (SSP) occurs when there is stenosis or occlusion of the subclavian artery. In SSP, which artery is stealing blood and shunting this to arms?","o":["External carotid","Internal carotid","Thyrocervical trunk","Vertebral artery","Cerebral artery"],"a":3,"e":"Subclavian steal: stenosis/occlusion of subclavian artery proximal to vertebral origin causes reverse flow in ipsilateral vertebral artery; blood is \"stolen\" from posterior circulation (basilar) into arm during exercise causing vertebrobasilar insufficiency.<br><br>Take Notes: Reverse vertebral flow → basilar territory ischemia | SSP stealing artery = vertebral artery."},
/*124*/ {"q":"A 25-year-old man is tackled during a football match, receiving a blow to the lateral side of his knee. He complains of pain on the knee and medial aspect of the knee and difficulty walking. Which of the following structures is most likely injured along with the medial collateral ligament (MCL)?","o":["Medial meniscus","Lateral meniscus","Tibial artery","Anterior cruciate ligament (ACL)","Lateral collateral ligament"],"a":0,"e":"O'Donoghue's unhappy triad: MCL + medial meniscus + ACL tear from valgus force at flexed knee. Medial meniscus attaches to MCL deep fibers, hence concurrent injury.<br><br>Take Notes: Lateral meniscus → less attached to LCL | Valgus knee injury = MCL + medial meniscus + ACL."},
/*125*/ {"q":"Failure of fusion of the medial ventricular walls in early embryonic life leads to which type of Ventricular Septal Defect (VSD)?","o":["Membranous VSD","Muscular VSD","Inlet VSD","Outlet VSD","Outflow VSD"],"a":0,"e":"Membranous VSD: failure of fusion of medial ventricular walls forming the membranous septum (most common VSD type — 80%). Muscular VSD results from failure of muscular septum development; inlet VSD from endocardial cushion abnormalities.<br><br>Take Notes: Muscular → muscular septum failure | Inlet → endocardial cushion | Membranous = medial ventricular walls (most common)."},
/*126*/ {"q":"A patient with type 2 diabetes is prescribed a drug that delays carbohydrate absorption in the intestine, lowering postprandial blood glucose. Which drug is this?","o":["Metformin","Glibenclamide","Acarbose","Pioglitazone","Sitagliptin"],"a":2,"e":"Acarbose is an α-glucosidase inhibitor; reduces intestinal carbohydrate absorption by inhibiting brush-border enzymes that break down disaccharides. Lowers postprandial glucose. Main side effect: GI symptoms (flatulence, diarrhea).<br><br>Take Notes: Metformin → decreases hepatic gluconeogenesis | Glibenclamide → insulin release | Postprandial glucose target + GI side effects = acarbose."},
/*127*/ {"q":"A 55-year-old male present to the clinic with complaint of increasing fatigue, shortness of breath, and palpitation over the past six months. He reports occasional chest discomfort and difficulty breathing when lying down. On examination, water hammer pulse and wide pulse pressure was present, on auscultation high pitched blowing diastolic murmur was heard. This is characteristic finding of which of the following conditions:","o":["Aortic stenosis","Aortic regurgitation","Mitral stenosis","Mitral regurgitation","Mitral valve prolapse"],"a":1,"e":"Aortic regurgitation: high-pitched blowing diastolic decrescendo murmur at left sternal border. Peripheral signs: water hammer pulse, wide pulse pressure. Volume overload heart failure.<br><br>Take Notes: Aortic stenosis → systolic, narrow pulse pressure | Mitral stenosis → mid-diastolic rumble | AR = diastolic + wide pulse pressure."},
/*128*/ {"q":"What is a likely side effect of consuming 2g of phenacetin?","o":["Hypertension","Methemoglobinemia","Hyperglycemia","Bradycardia","Lactic acidosis"],"a":1,"e":"Phenacetin (analgesic, now withdrawn) causes methemoglobinemia (oxidation of Hb iron from Fe²⁺ to Fe³⁺), reducing O2 carrying capacity. Also causes interstitial nephritis (analgesic nephropathy) with prolonged use.<br><br>Take Notes: Other Met-Hb causes → benzocaine, dapsone, nitrates | Phenacetin = methemoglobinemia + analgesic nephropathy."},
/*129*/ {"q":"Pioglitazone's mechanism of action involves agonism of which receptor?","o":["PPAR-α","PPAR-γ","GLP-1 receptor","SGLT2","Alpha-glucosidase"],"a":1,"e":"Pioglitazone (thiazolidinedione, TZD) is a PPAR-γ agonist; activates this nuclear receptor in adipose tissue, muscle, and liver, increasing insulin sensitivity and adiponectin. Improves lipid profile but causes fluid retention.<br><br>Take Notes: Fibrates → PPAR-α (lipid lowering) | TZDs = PPAR-γ (insulin sensitizers)."},
/*130*/ {"q":"A 65-year-old patient with a history of stroke, AFib, and CKD is on stable hemodialysis. Which anticoagulant is most suitable?","o":["Dabigatran","Apixaban","Rivaroxaban","Warfarin","Edoxaban"],"a":3,"e":"Warfarin is the only anticoagulant adequately studied and recommended for atrial fibrillation in patients on hemodialysis (ESRD); other DOACs (dabigatran, apixaban, rivaroxaban) have varied excretion and limited dialysis safety data.<br><br>Take Notes: Dabigatran → significant renal clearance | Apixaban → least renal but caution in HD | ESRD + AFib = warfarin."},
/*131*/ {"q":"Cheilosis and corneal vascularization is due to deficiency of which vitamin?","o":["Thiamine","Biotin","Riboflavin","Folate","Vitamin C"],"a":2,"e":"Vitamin B2 (riboflavin) deficiency: cheilosis (angular cracking of mouth), glossitis, seborrheic dermatitis, and corneal vascularization. Riboflavin is essential cofactor for FMN and FAD coenzymes in electron transport.<br><br>Take Notes: Thiamine (B1) → beriberi, Wernicke | Niacin (B3) → pellagra | Cheilosis + corneal vasc = riboflavin."},
/*132*/ {"q":"Which protein is a key component of neurofibrillary tangles in Alzheimer's disease?","o":["GFAP","Tau protein","Amyloid beta","Alpha-synuclein","Prion protein"],"a":1,"e":"Alzheimer disease hallmarks: extracellular amyloid plaques (Aβ from APP cleavage) and intracellular neurofibrillary tangles of hyperphosphorylated tau protein. Tau normally stabilizes microtubules; abnormal hyperphosphorylation causes aggregation.<br><br>Take Notes: Amyloid beta → extracellular plaques | Alpha-synuclein → Lewy bodies (Parkinson, LBD) | Neurofibrillary tangles = tau protein."},
/*133*/ {"q":"Hirschsprung's disease primarily affects which part of the large intestine?","o":["Ascending colon","Sigmoid colon","Cecum","Rectum","Transverse colon"],"a":3,"e":"Hirschsprung disease (congenital aganglionic megacolon): most commonly affects rectosigmoid region (75% of cases); aganglionic segment causes functional obstruction. Failure of neural crest cell migration to distal bowel during embryogenesis.<br><br>Take Notes: Total colonic aganglionosis → 5% | Short segment most common → rectosigmoid | Hirschsprung = rectum (most affected)."},
/*134*/ {"q":"Most common cause of pansystolic murmur?","o":["ASD","TOF","VSD","PDA","Aortic stenosis"],"a":2,"e":"VSD (ventricular septal defect) is the most common cause of pansystolic (holosystolic) murmur. Best heard at left lower sternal border. Mitral and tricuspid regurgitation also produce pansystolic murmurs in different locations.<br><br>Take Notes: Mitral regurg → pansystolic at apex | Tricuspid regurg → pansystolic at LLSB | Most common pansystolic = VSD."},
/*135*/ {"q":"Maple syrup urine disease is an inborn error of metabolism. Which enzyme is deficient?","o":["Homogentisic acid oxidase","Aromatic amino acid ketolase","Branched chain alpha ketoacid dehydrogenase","Propyl hydroxylase","Phenylalanine hydroxylase"],"a":2,"e":"Maple syrup urine disease (MSUD): branched-chain α-ketoacid dehydrogenase deficiency causes accumulation of branched-chain amino acids (leucine, isoleucine, valine) and their α-keto acids; produces characteristic maple syrup odor of urine.<br><br>Take Notes: Homogentisic acid oxidase → alkaptonuria | Phenylalanine hydroxylase → PKU | MSUD = branched-chain α-ketoacid dehydrogenase."},
/*136*/ {"q":"Crumpled tissue paper-like macrophages. Gaucher disease is caused by deficiency of which enzyme?","o":["Hexosaminidase A","Glucocerebrosidase","Sphingomyelinase","Hexosaminidase","Glucokinase"],"a":1,"e":"Gaucher disease: most common lysosomal storage disease; β-glucocerebrosidase deficiency causes glucocerebroside accumulation in macrophages (Gaucher cells with \"crumpled tissue paper\" cytoplasm). Hepatosplenomegaly, pancytopenia, bone pain.<br><br>Take Notes: Hexosaminidase A → Tay-Sachs (cherry red spot) | Sphingomyelinase → Niemann-Pick | Gaucher = glucocerebrosidase."},
/*137*/ {"q":"Type 1 hyperlipidemia with increased VLDL and TG is due to:","o":["Deficiency of Lipoprotein lipase","Apo C1 mutation","Apo E deficiency","LDL receptor deficiency","Deficiency of Apo B"],"a":0,"e":"Type 1 hyperlipoproteinemia (familial chylomicronemia): lipoprotein lipase (LPL) or Apo CII deficiency causes failed clearance of chylomicrons (rich in TGs); markedly elevated triglycerides, eruptive xanthomas, pancreatitis risk.<br><br>Take Notes: LDL receptor → type 2a (familial hypercholesterolemia) | Apo E → type 3 (dysbetalipoproteinemia) | Chylomicronemia (Type 1) = LPL deficiency."},
/*138*/ {"q":"Security guard had history of fall and remained unconscious for 30 seconds. His neurological examination is unremarkable. He is having irregular pulse. What is the cause?","o":["Syncope","MI","Heat stroke","Transient ischemic attack","Seizure"],"a":0,"e":"Cardiogenic syncope from arrhythmia (irregular pulse): brief LOC due to reduced cerebral perfusion. Normal neurological exam after recovery is consistent with syncope (TIA usually has focal signs; seizure has postictal state).<br><br>Take Notes: TIA → focal neuro signs | Seizure → postictal confusion | Brief LOC + irregular pulse + normal neuro = syncope."},
/*139*/ {"q":"A neonate presents with failure to thrive, vomiting, musty body odor, fair skin, blue eyes, developmental delays, and a positive ferric chloride test in urine. What is the likely diagnosis?","o":["Alkaptonuria","Phenylketonuria","Homocystinuria","Tropoaminase 1","Tropoaminase 2"],"a":1,"e":"Phenylketonuria (PKU): phenylalanine hydroxylase deficiency; phenylalanine accumulation causes musty odor (phenylacetate), fair skin/blue eyes (decreased melanin from tyrosine deficiency), developmental delay, seizures. Ferric chloride test positive. Newborn screening with Guthrie test.<br><br>Take Notes: Alkaptonuria → black urine | Homocystinuria → ectopia lentis | Musty odor + fair skin + neuro = PKU."},
/*140*/ {"q":"A female is found with an empty benzodiazepine bottle after a fight. BP 90/60. What can be given at home?","o":["Flumazenil","Morphine","Activated charcoal","Naloxone","Atropine"],"a":0,"e":"Flumazenil is the specific benzodiazepine receptor antagonist; reverses BZD overdose (sedation, respiratory depression). However, can precipitate seizures in chronic BZD users — used cautiously in hospital setting (this question's framing is unusual).<br><br>Take Notes: Naloxone → opioid antidote | Activated charcoal → general decontamination | BZD specific antidote = flumazenil."},
/*141*/ {"q":"Patient was having bronchiolar inflammation and increased productive cough. What is the progenitor cell of the structure damaged in this condition?","o":["Basal cell","Granular cell","Clara cell","Goblet cell","Type II pneumocyte"],"a":2,"e":"Clara (Club) cells are non-ciliated columnar cells in distal bronchioles; act as stem/progenitor cells for bronchiolar epithelium repair. Also secrete surfactant components and detoxify inhaled toxins via CYP450.<br><br>Take Notes: Basal cells → tracheal/large airway progenitor | Type II pneumocyte → alveolar progenitor | Bronchiolar progenitor = Clara cell."},
/*142*/ {"q":"Tumor marker of astrocytes:","o":["GFAP","CEA","CA 125","CA 19-9","FAP"],"a":0,"e":"Glial fibrillary acidic protein (GFAP) is the immunohistochemical marker for astrocytes and astrocytic tumors (astrocytoma, glioblastoma, ependymoma). An intermediate filament protein specific to astrocytes and glial cells.<br><br>Take Notes: CEA → colon | CA 125 → ovary | CA 19-9 → pancreas | Astrocyte/glial marker = GFAP."},
/*143*/ {"q":"A child previously having TB comes to you with complaint of fever and cough along with noisy breathing and difficulty in swallowing, now diagnosed as retropharyngeal which structure it will invade through?","o":["Pre-cervical fascia","Prevertebral fascia","Carotid sheath","Buccopharyngeal fascia","Pretracheal fascia"],"a":1,"e":"Retropharyngeal abscess (Pott's disease/TB of cervical spine): infection arises behind prevertebral fascia, can extend into prevertebral space causing dysphagia, dyspnea, neck stiffness. Spreads inferiorly into posterior mediastinum.<br><br>Take Notes: Pretracheal → anterior mediastinum spread | Buccopharyngeal → covers pharynx | Retropharyngeal/Pott's = prevertebral fascia."},
/*144*/ {"q":"An abscess in the posterior triangle of the neck, superior to the sternocleidomastoid muscle, is likely to spread to:","o":["Investing layer of deep cervical fascia","Pretracheal fascia","Retromandibular space","Prevertebral fascia","Carotid sheath"],"a":3,"e":"Posterior triangle abscess spreads through deep cervical fascia layers; prevertebral fascia is the most posterior layer extending from skull base to coccyx, allowing infection spread to vertebral region and inferiorly.<br><br>Take Notes: Pretracheal → anterior, surrounds trachea | Investing → most superficial | Posterior triangle deep spread = prevertebral fascia."},
/*145*/ {"q":"A patient with head injury: urine output 500 mL/h, urine osmolality 800, serum osmolality 250, serum potassium 3.5. Diagnosis?","o":["SIADH","Diabetes insipidus","Cerebral salt wasting","Addison's crisis","Hypopituitarism"],"a":2,"e":"Cerebral salt wasting (CSW): post-head injury hyponatremia with HIGH urine output (volume depletion) and HIGH urine osmolality (inappropriate sodium excretion). Differs from SIADH (low urine output, euvolemia/hypervolemia).<br><br>Take Notes: SIADH → low urine output + euvolemia | DI → dilute urine | CSW = high urine output + concentrated urine + hyponatremia."},
/*146*/ {"q":"A 32-year-old man sustains a blow to the head in a road traffic accident. Examination reveals ptosis, a dilated pupil, and the eye deviated \"down and out\" on the left side. Injury to which of the following skull structures most likely caused his symptoms?","o":["Greater wing of sphenoid","Lesser wing of sphenoid","Superior orbital fissure","Ethmoid bone","Frontal bone"],"a":2,"e":"Superior orbital fissure transmits CN III, IV, VI and V1 (ophthalmic). Injury causes complete ophthalmoplegia: ptosis, mydriasis, \"down and out\" eye (CN III palsy).<br><br>Take Notes: Greater wing → V2, V3 | Lesser wing → CN II | Down/out/ptosis = superior orbital fissure (CN III)."},
/*147*/ {"q":"The supraorbital artery is a branch of:","o":["Ophthalmic artery","Maxillary artery","Facial artery","Superficial temporal artery","Middle meningeal artery"],"a":0,"e":"Supraorbital artery is a branch of the ophthalmic artery (branch of internal carotid); supplies forehead and scalp above orbital margin. Exits through supraorbital foramen with supraorbital nerve.<br><br>Take Notes: Superficial temporal → preauricular scalp | Facial → cheek + lips | Supraorbital artery = ophthalmic artery branch."},
/*148*/ {"q":"A patient presented with signs of hypovolemic shock and received treatment for this very cause. What indicator should be assessed for initial recovery in him?","o":["Increase cardiac output","Increase HR","Increase urine output","Edema","Increase BP"],"a":2,"e":"Increased urine output (>0.5 mL/kg/h) is the best indicator of adequate end-organ perfusion and initial recovery from shock; reflects restored renal blood flow.<br><br>Take Notes: HR/BP → misleading (compensatory) | UO = best perfusion indicator | Shock recovery = urine output."},
/*149*/ {"q":"Chloramphenicol's mechanism of action is:","o":["Inhibit protein synthesis","Inhibit cell wall synthesis","Inhibit DNA replication","Inhibit RNA synthesis","Inhibit folate synthesis"],"a":0,"e":"Chloramphenicol inhibits bacterial protein synthesis by binding 50S ribosomal subunit (peptidyl transferase blocked). Reserved use due to aplastic anemia (idiosyncratic, irreversible) and grey baby syndrome in neonates.<br><br>Take Notes: Cell wall → β-lactams | DNA replication → fluoroquinolones | Chloramphenicol = 50S ribosome (protein synthesis)."},
/*150*/ {"q":"A 45-year-old asthmatic patient with a history of myocardial infarction presents for fitness evaluation. ASA classification will be:","o":["ASA 1","ASA 2","ASA 3","ASA 4","ASA 5"],"a":2,"e":"ASA 3: severe systemic disease not life-threatening (asthma + history of MI = significant comorbidities affecting daily function but not incapacitating).<br><br>Take Notes: ASA 1 → healthy | ASA 2 → mild disease | ASA 4 → life-threat | Asthma + MI history = ASA 3."},
/*151*/ {"q":"A patient is placed in the left lateral position before surgery despite not being NPO. Why?","o":["To improve ventilation in the left lung","Right bronchus is wider and vertical, has more chance of aspiration","To improve venous return","To reduce pressure on the spine","To reduce gastric pressure"],"a":1,"e":"Right main bronchus is more vertical, wider, and shorter than left; aspirated material preferentially enters right lung. Left lateral position places left side down — aspiration (if vomiting) flows away from open airway protecting non-dependent lung.<br><br>Take Notes: Right main bronchus → more vertical (aspiration risk) | Left lateral position = aspiration prevention."},
/*152*/ {"q":"A 36-week pregnant patient presents with labour and fetal bradycardia. This is a sign of:","o":["Fetal hypoxia","Fetal tachycardia","Maternal anemia","Polyhydramnios","Placental insufficiency"],"a":0,"e":"Fetal bradycardia (<110 bpm) during labour is a sign of fetal hypoxia and distress; commonly from cord compression, placental insufficiency, or maternal hypotension. Requires immediate intervention (position change, O2, possible C-section).<br><br>Take Notes: Late decelerations → uteroplacental insufficiency | Variable decelerations → cord compression | Fetal bradycardia = hypoxia."},
/*153*/ {"q":"A patient with trauma on the ventral border of the scapula is unable to move. Which muscle is likely ruptured?","o":["Trapezius","Latissimus dorsi","Pectoralis major","Serratus anterior","Rhomboid major"],"a":3,"e":"Serratus anterior originates from upper 8-9 ribs and inserts on costal (ventral/anterior) surface of scapula. Damage causes winging of scapula and inability to elevate arm above 90°. Long thoracic nerve injury can also cause this.<br><br>Take Notes: Trapezius → upper back | Rhomboid major → between scapulae | Ventral scapular border attachment = serratus anterior."},
/*154*/ {"q":"A patient develops tPA toxicity with increased ICP after stroke treatment. Best reversal method:","o":["Cryoprecipitate","Fresh frozen plasma","Vitamin K","Protamine sulfate","Tranexamic acid"],"a":0,"e":"tPA toxicity with bleeding/ICH: cryoprecipitate contains fibrinogen, factor VIII, vWF, factor XIII — replaces fibrinogen depleted by tPA-induced fibrinolysis. Used first-line. Tranexamic acid (antifibrinolytic) also useful.<br><br>Take Notes: FFP → coagulation factors | Vitamin K → warfarin reversal | Protamine → heparin | tPA reversal = cryoprecipitate (fibrinogen)."},
/*155*/ {"q":"Local anesthetics primarily act on:","o":["Voltage gated Na channels","Calcium channels","Na/K pump","GABA receptors","Acetylcholine receptors"],"a":0,"e":"Local anesthetics (lidocaine, bupivacaine) block voltage-gated sodium channels in nerve fibers preventing depolarization and action potential propagation. Reversible block; effect on small unmyelinated fibers first (pain, then temperature, touch, motor).<br><br>Take Notes: Class I antiarrhythmics → also Na+ channels (cardiac) | GABA receptors → BZDs | Local anesthetic MOA = voltage-gated Na+ channels."},
/*156*/ {"q":"A 45-year-old male patient is admitted to the ICU after a craniotomy for a right frontal tumor. Which of the following interventions is most effective in preventing an increase in intracranial pressure (ICP) in the postoperative period?","o":["Elevating the head of the bed to 30 degrees","Administering prophylactic mannitol routinely","Keeping the patient NPO for 48 hours","Routine hyperventilation to PaCO2 of 25 mmHg","Strict supine position"],"a":0,"e":"Elevating head of bed to 30° improves cerebral venous drainage and decreases ICP; first-line intervention in neurosurgical/head injury patients. Mannitol used for acute ICP rise (not prophylactic). Avoid hyperventilation routinely (cerebral ischemia).<br><br>Take Notes: Hyperventilation → only for impending herniation | Mannitol → acute rise | ICP prevention = head elevation 30°."},
/*157*/ {"q":"A patient with Familial Adenomatous Polyposis (FAP) develops a fibrous central abdominal tumor. The likely diagnosis is:","o":["Desmoid tumor","Lipoma","Leiomyoma","Gastrointestinal stromal tumor","Sarcoma"],"a":0,"e":"Gardner syndrome (FAP variant) includes desmoid tumors: locally aggressive but non-metastasizing fibrous tumors arising from musculoaponeurotic structures (especially mesenteric); benign histology but locally destructive. Associated with APC gene mutation.<br><br>Take Notes: Lipoma → fat | Leiomyoma → smooth muscle | GIST → c-KIT | FAP + fibrous tumor = desmoid (Gardner syndrome)."},
/*158*/ {"q":"A patient with history of appendectomy for mucinous carcinoma presents with ascites, altered bowel habits, and \"sticky\" abdomen on examination. Likely diagnosis?","o":["Peritoneal carcinomatosis","Pseudomyxoma peritonei","Tuberculous peritonitis","Mesenteric panniculitis","Krukenberg tumor"],"a":1,"e":"Pseudomyxoma peritonei: rare condition with intraperitoneal mucinous ascites and tumor implants on peritoneum; commonly from appendiceal mucinous neoplasms (also ovarian). \"Sticky\" gelatinous ascites; \"jelly belly\" presentation.<br><br>Take Notes: Peritoneal carcinomatosis → non-mucinous | TB peritonitis → caseous granulomas | Appendiceal mucinous CA + sticky ascites = pseudomyxoma peritonei."},
/*159*/ {"q":"A patient merely eats vegetables, he will be deficient in:","o":["Folic acid","Vitamin B12","Calcium","Iron","Vitamin K"],"a":1,"e":"Vegetarian/vegan diet lacks vitamin B12 (cobalamin) — found only in animal products. Plants contain folate adequately. B12 deficiency causes megaloblastic anemia with neurological symptoms (subacute combined degeneration); long latency before symptoms (years).<br><br>Take Notes: Folate → ample in vegetables | Iron/calcium → possible but easier to supplement | Strict vegetarian = B12 deficiency."},
/*160*/ {"q":"A lactating mother presents with a breast mass. FNAC shows white creamy material. Likely diagnosis?","o":["Breast abscess","Galactocele","Fibroadenoma","Breast carcinoma","Cystic mastitis"],"a":1,"e":"Galactocele: milk-filled cyst in breast, typically in lactating or recently lactating women. FNAC reveals milky white creamy fluid. Self-limiting; usually resolves spontaneously or with aspiration.<br><br>Take Notes: Breast abscess → pus, hot tender mass | Fibroadenoma → solid | Carcinoma → hard fixed | Lactating + milky aspirate = galactocele."},
];
